INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('A', 'NYPD', 'NYPD overtime peaked in FY2025 and came down in FY2026, but still outpaces the budget', 'Overtime went from $871.2M in FY2023 to a peak of $1,135.6M in FY2025, then fell 15.0% to $965.7M in FY2026. Over the full window it is still up 10.8%, against 8.2% growth in total spending, and it remains 14.0% of the department budget. The FY2026 drop is the first sign of a turn. One year does not yet make a structural change, which is the bar Executive Order 12 sets.', 'Values are as reported in each year''s MMR. Later reports can restate a prior year, so year-over-year changes may differ slightly from the latest MMR tables.', 1);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('A', 'DOC', 'DOC overtime kept climbing and is now over a quarter of the budget', 'Overtime rose 24.5% from FY2023 to FY2026 ($296.4M to $369.1M), while total spending grew only 1.6%. FY2026 added another 8.2% on top of FY2025. Overtime''s share of the budget went from 21.8% to 26.7%. Unlike NYPD, there is no turn yet. This is the clearest recurring cost pressure in the scan.', 'Staffing levels, absence rates and court-ordered requirements need internal data to explain.', 2);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('A', 'DOF', 'DOF''s FY2025 overtime spike reversed in FY2026', 'Through FY2025, DOF overtime had grown 142.5% ($2.1M to $5.1M). In FY2026 it fell back to $2.0M, 5.2% below FY2023. The spike looks like a one-year event rather than a trend. That is a useful result in itself: a second year of data can clear an outlier as well as confirm one.', 'DOF reports overtime in thousands of dollars. Values here are converted to millions for comparison.', 3);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('A', 'DSNY', 'DSNY overtime jumped 60% in FY2026 alone', 'Sanitation overtime was roughly flat through FY2025 ($165.6M to $201.0M), then rose 60.5% to $322.7M in FY2026, the largest one-year jump among big-budget agencies. Over four years overtime grew 94.9% against 23.0% for total spending, and its share of the budget went from 8.6% to 13.7%. The budget itself also grew fast in FY2026, which points to expanded service rather than a pure overtime problem. Whether it is a one-year surge or a new baseline is the question FY2027 will answer.', 'Sanitation overtime swings with snow season and service expansions. One year of growth is a question, not a trend.', 4);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'SBS', 'SBS: spending up, outcomes flat or down', 'Spending rose 48.6% from FY2023 to FY2026, while the median performance trend was 0.0% (3/7 indicators improving). Worth a closer look with the agency. Not a conclusion on its own.', 'Outcome score is the median of MMR indicators that have values in both FY2023 and FY2026.', 11);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'ACS', 'ACS: spending up, outcomes flat or down', 'Spending rose 40.6% from FY2023 to FY2026, while the median performance trend was 1.7% (28/51 indicators improving). Worth a closer look with the agency. Not a conclusion on its own.', 'Outcome score is the median of MMR indicators that have values in both FY2023 and FY2026.', 12);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'OATH', 'OATH: spending up, outcomes flat or down', 'Spending rose 27.4% from FY2023 to FY2026, while the median performance trend was -5.5% (0/4 indicators improving). Worth a closer look with the agency. Not a conclusion on its own.', 'Outcome score is the median of MMR indicators that have values in both FY2023 and FY2026.', 13);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'HRA', 'HRA: spending up, outcomes flat or down', 'Spending rose 25.2% from FY2023 to FY2026, while the median performance trend was 0.0% (13/29 indicators improving). Worth a closer look with the agency. Not a conclusion on its own.', 'Outcome score is the median of MMR indicators that have values in both FY2023 and FY2026.', 14);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'OCME', 'OCME: spending up, outcomes flat or down', 'Spending rose 22.8% from FY2023 to FY2026, while the median performance trend was 0.4% (7/14 indicators improving). Worth a closer look with the agency. Not a conclusion on its own.', 'Outcome score is the median of MMR indicators that have values in both FY2023 and FY2026.', 15);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'CCHR', 'CCHR entered the zone once FY2026 was added', 'Through FY2025, spending was +8.5% and the median outcome trend +45.6%. Through FY2026, spending is +13.7% and outcomes -11.9%. The largest moves in the wrong direction: training and outreach sessions (131 to 27) and complaints successfully mediated (2 to 1).', 'Both windows are scored with the same method and the same data download (FY2023 to FY2025 vs FY2023 to FY2026).', 21);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'DOB', 'DOB entered the zone once FY2026 was added', 'Through FY2025, spending was -3.1% and the median outcome trend -14.2%. Through FY2026, spending is +5.1% and outcomes -35.8%. The largest moves in the wrong direction: average days to complete first plan review, minor renovations, initial applications (3.5 to 15.8) and average days between electrical inspection request and inspection (4.2 to 15.9).', 'Both windows are scored with the same method and the same data download (FY2023 to FY2025 vs FY2023 to FY2026).', 22);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'HPD', 'HPD left the zone once FY2026 was added', 'Through FY2025, spending was +46.6% with a median outcome trend of -7.7%. Through FY2026, outcomes moved to +12.1% with spending at +39.8%. The added cost now comes with measurable improvement.', 'Both windows are scored with the same method and the same data download (FY2023 to FY2025 vs FY2023 to FY2026).', 23);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'DYCD', 'DYCD left the zone once FY2026 was added', 'Through FY2025, spending was +15.9% with a median outcome trend of +1.2%. Through FY2026, outcomes moved to +16.0% with spending at +27.2%. The added cost now comes with measurable improvement.', 'Both windows are scored with the same method and the same data download (FY2023 to FY2025 vs FY2023 to FY2026).', 24);
INSERT INTO ny_findings (pane, agency, title, body, caveat, sort_order) VALUES ('B', 'DOF', 'DOF left the zone once FY2026 was added', 'Through FY2025, spending was +4.7% with a median outcome trend of -0.3%. Through FY2026, outcomes moved to +2.3% with spending at +9.1%. The added cost now comes with measurable improvement.', 'Both windows are scored with the same method and the same data download (FY2023 to FY2025 vs FY2023 to FY2026).', 25);
INSERT INTO ny_meta (key, value) VALUES ('data_vintage', '2026-10-27');
INSERT INTO ny_meta (key, value) VALUES ('methodology', 'Built from NYC Open Data Mayor''s Management Report agency resources and performance indicators for FY2023 to FY2026, including the Fiscal 2026 MMR released in September 2026. The earlier FY2023 to FY2025 window is scored with the same method so the effect of the newest year is visible. Pane A compares overtime growth to total spending. Pane B joins spending growth to a median performance trend. The target zone is where cost rose and outcomes stayed flat or moved the wrong way.');
INSERT INTO ny_meta (key, value) VALUES ('eo12_framing', 'Executive Order 12 (January 2026) asks each agency to find recurring, structural savings, not one-time cuts. Public data can only point to places worth asking about.');
INSERT INTO ny_meta (key, value) VALUES ('disclaimer', 'This is an independent analysis of public data. It is not an audit and not an official finding.');
INSERT INTO ny_meta (key, value) VALUES ('window', 'FY2023 to FY2026');
INSERT INTO ny_meta (key, value) VALUES ('prev_window', 'FY2023 to FY2025');
INSERT INTO ny_meta (key, value) VALUES ('zone_count', '15');
INSERT INTO ny_meta (key, value) VALUES ('zone_count_prev', '16');
INSERT INTO ny_meta (key, value) VALUES ('zone_entered', '2');
INSERT INTO ny_meta (key, value) VALUES ('zone_left', '3');
INSERT INTO ny_reach_programs (program, program_label, eligible_population, enrolled_population, takeup_rate_pct, population_year, headline, note, source_label, source_url, sort_order) VALUES ('SNAP', 'SNAP (food assistance)', 2280000.0, 1790000.0, 78.6, 2024, 'About 4 in 5 eligible New Yorkers receive SNAP', 'HRA estimates 1.79 million New Yorkers received SNAP in 2024, a participation rate of 78.6% among people the Census ACS suggests are eligible. By a second, broader federal measure, the Program Access Index, NYC reached 95.7%, its highest on record. The two measures use different eligibility definitions; both point the same direction: SNAP outreach and renewal in NYC works well. The Fiscal 2026 MMR reports SNAP recipients fell 7% to 1.68 million, which HRA attributes mainly to federal eligibility changes under H.R.1 (July 2025), so the 2024 rate should not be read as current.', 'NYC HRA, SNAPShot (March 2026)', 'https://www.nyc.gov/assets/hra/downloads/pdf/facts/snap/SNAPParticipationNYC.pdf', 1);
INSERT INTO ny_reach_programs (program, program_label, eligible_population, enrolled_population, takeup_rate_pct, population_year, headline, note, source_label, source_url, sort_order) VALUES ('FAIR_FARES', 'Fair Fares (half-price transit)', 950000.0, 370000.0, 38.9, 2026, 'Fewer than 2 in 5 eligible New Yorkers use Fair Fares', 'The city expanded Fair Fares eligibility to 200% of the federal poverty line in mid-2026, growing the eligible pool to roughly 950,000 people. Enrollment has not caught up: about 370,000 people were enrolled as of July 2026, a take-up rate near 39%. Widening who qualifies did not by itself close the gap; the application step still is.', 'PCAC, Fair Fares expansion report (2026)', 'https://pcac.org/report/fairfares/', 2);
INSERT INTO ny_reach_programs (program, program_label, eligible_population, enrolled_population, takeup_rate_pct, population_year, headline, note, source_label, source_url, sort_order) VALUES ('FAIR_FARES_VERIFIED_OVERLAP', 'Fair Fares, among people already verified eligible for other benefits', NULL, NULL, 66.0, 2026, 'Even pre-verified New Yorkers fall through the cracks', 'In a 2026 survey of 1,616 New Yorkers already receiving SNAP, Cash Assistance, or CityFHEPS, the same agency (HRA) that already verified their income for those programs, about two-thirds were enrolled in Fair Fares. More than one in three were not, despite the city already holding the income data needed to auto-enroll them. That is a process gap, not an eligibility gap.', 'Community Service Society of NY (2026)', 'https://www.cssny.org/news/entry/fair-fares-nyc-expansion-who-qualifies-whats-changing-and-why-it-matters-new-yorkers', 3);
